// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzzed param: an arbitrary caller address to query owner() from (fuzzer supplies many addresses)
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid the zero address to ensure a meaningful owner in reference
        vm.assume(caller != address(0));

        // The reference contract stores owner as set in constructor (address(this) at deployment)
        // We query owner() as if called by arbitrary caller. Owner getter is view and should return
        // the stored owner independent of msg.sender. We capture the returned address via try/catch
        // to handle both contracts that may revert or not; here owner() should not revert.

        bool ok;
        address returned;
        try c.owner() returns (address o) {
            ok = true;
            returned = o;
        } catch {
            ok = false;
            returned = address(0);
        }

        // The general rule: the correct contract's owner() returns the stored owner (which equals
        // the deploying address set in constructor). In our setup that is address(this) (the test
        // contract) and is not the zero address. Therefore owner() must return non-zero and equal
        // address(this). The mutant that always returns address(0) will violate this for this input.
        assertTrue(ok && returned == address(this));
    }
}

