pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ProxyCaller proxy;

    function setUp() public {
        // deploy C with constructor args as required by the harness
        // per instructions: new C(address(this), 0, 0, address(this))
        c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0));
        // deploy a proxy contract that will call c.owner() on behalf of an EOA
        proxy = new ProxyCaller();
    }

    // General rule we assert: calling c.owner() via an intermediate contract returns the stored owner (deployer)
    // For the reference implementation this will be true for all fuzzed addresses; the mutant returning tx.origin
    // will return the original EOA (fuzzer-supplied caller) when invoked through the proxy, causing a difference
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero to be meaningful; allow zero as well but it's fine either way
        // we will use the fuzzed `caller` as the tx.origin when proxy calls c.owner(); to simulate an EOA we
        // prank to that address before calling proxy which forwards the call to c.

        // vm.prank sets msg.sender for next call; to make tx.origin equal to `caller`, we need an EOA initiating the tx.
        // In Foundry, vm.prank(addr) makes msg.sender == addr and tx.origin == addr for the next call.
        // We use that to have the EOA `caller` call the proxy, which then calls c.owner().

        // Ensure caller is a regular address space (no constraint needed), but avoid the proxy’s own address
        vm.assume(caller != address(proxy));

        // Have the fuzzed EOA call the proxy which will in turn call c.owner()
        vm.prank(caller);
        address ownerViaProxy = proxy.callOwner(address(c));

        // Direct call by this test contract (deployer) should return the stored owner (this contract)
        address directOwner = c.owner();

        // The universal property for the reference: when called through an intermediate contract, owner() returns the same stored owner as direct call (owner is stored and independent of tx.origin).
        // Therefore assert equality between directOwner and ownerViaProxy. For the mutant that returns tx.origin, ownerViaProxy == caller, which will differ for some fuzzed caller, causing the test to fail.
        assertTrue(directOwner == ownerViaProxy);
    }
}

// Minimal adversarial helper: a simple contract that forwards an external call to c.owner() and returns the result.
contract ProxyCaller {
    function callOwner(address target) external returns (address) {
        (bool ok, bytes memory ret) = target.call(abi.encodeWithSelector(bytes4(keccak256("owner()"))));
        require(ok, "call failed");
        return abi.decode(ret, (address));
    }
}

