pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzzed param is an arbitrary address that we will use as an EOA to call through a relay contract
    function testFuzz_property(address callerEOA) public {
        // keep callerEOA non-zero and not equal to this (deployer) to allow meaningful tx.origin differences
        vm.assume(callerEOA != address(0));
        vm.assume(callerEOA != address(this));

        // Deploy a tiny relay contract that will call c.owner() and return the observed owner via a view call
        Relay relay = new Relay(address(c));

        // We need to have the EOA be able to act as tx.origin when calling through relay.
        // In Foundry tests, we can impersonate the EOA with vm.prank to make it the tx.origin for the external call.
        vm.prank(callerEOA);
        address observedOwner = relay.queryOwner(); // this performs an external call from the relay to c.owner() with tx.origin = callerEOA

        // The universal property: the reference contract's owner() should always equal the deployer (address(this))
        // when observed via any caller (EOA or contract). We assert that observedOwner == address(this).
        // The mutant (owner() returns tx.origin) will make this assertion fail for some callerEOA (specifically any callerEOA != deployer)
        assertTrue(observedOwner == address(this));
    }
}

// Minimal relay that queries c.owner() from its own context. The relay will be called with tx.origin set to the fuzzed EOA.
contract Relay {
    C public c;
    constructor(address _c) { c = C(_c); }
    function queryOwner() external view returns (address) {
        return c.owner();
    }
}

