pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzz a caller address seed to deploy an intermediate caller contract at a derived address
    function testFuzz_property(uint256 salt) public {
        // General rule to check: for any caller, calling c.owner() should return the deployer (address(this) set at construction)
        // We exercise the case where a contract calls c.owner() so tx.origin != callerContract

        // Derive a pseudo-random private key/address from salt to act as an EOA origin
        // Use vm to create an address with funds
        address eoa = address(uint160(uint256(keccak256(abi.encodePacked(salt, "eoa")))));
        vm.assume(eoa != address(0));
        vm.deal(eoa, 1 ether);

        // Deploy a small caller contract from that EOA (so tx.origin == eoa, msg.sender == callerContract)
        vm.prank(eoa);
        Caller caller = new Caller();

        // Now, from the EOA, have the caller contract call c.owner() (so inside call: msg.sender = caller, tx.origin = eoa)
        // We cannot directly make caller call using vm.prank for the EOA because the call originates from EOA to the caller (already deployed),
        // so we use vm.prank(eoa) to invoke caller.callOwner(c)
        vm.prank(eoa);
        address returned = caller.callOwner(address(c));

        // The reference implementation always returns the deployer address (which we set to address(this) in setUp)
        // Assert that c.owner() as observed through the intermediate contract equals the deployer (address(this)).
        // This will hold for the reference but fail for the mutant that returns tx.origin when tx.origin != deployer.
        assertTrue(returned == address(this));
    }
}

contract Caller {
    // call owner() on target and return the observed address
    function callOwner(address target) external returns (address) {
        (bool ok, bytes memory ret) = target.call(abi.encodeWithSignature("owner()"));
        require(ok, "call failed");
        return abi.decode(ret, (address));
    }
}

