pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzz parameter: an address that will act as an EOA originator
    function testFuzz_property(address originEOA) public {
        // keep originEOA non-zero to be meaningful
        vm.assume(originEOA != address(0));

        // Deploy an intermediate caller contract that will call c.owner()
        Caller caller = new Caller(address(c));

        // The reference contract's owner() should always return the deployer (address(this) from setUp())
        // When invoked directly (by any caller) it should still report the stored owner value.
        // We will simulate a tx where an external EOA originEOA calls the intermediate Caller, which in turn calls c.owner().

        // Fund the originEOA so it can make a call (not strictly necessary but keeps environment realistic)
        vm.deal(originEOA, 1 ether);

        // Simulate the call coming from originEOA to the Caller contract which then calls c.owner()
        vm.prank(originEOA);
        address returnedOwner = caller.callOwner();

        // The original (reference) contract was deployed in setUp() with deployer address(this).
        // So regardless of originEOA and intermediate caller, owner() should equal address(this).
        // The mutant returning tx.origin would return originEOA instead when called via Caller, thus violating this.
        assertTrue(returnedOwner == address(this));
    }
}

// Minimal helper that calls c.owner() and returns the result
contract Caller {
    C immutable target;
    constructor(address _target) { target = C(_target); }
    function callOwner() external returns (address) {
        return target.owner();
    }
}

// Note: The interfaces used in setUp() are referenced by C; to satisfy the compiler
interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}
interface ICVXBooster {
    struct PoolInfo { address lptoken; address token; address gauge; address crvRewards; address stash; bool shutdown; }
    function poolInfo(uint256 _pid) external view returns (PoolInfo memory);
    function depositAll(uint256 _pid, bool _stake) external returns (bool);
    function withdrawAll(uint256 _pid) external returns (bool);
    function deposit(uint256 _pid, uint256 _amount, bool _stake) external returns (bool);
    function withdraw(uint256 _pid, uint256 _amount) external returns (bool);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzzed params: an EOA caller address and a random salt to ensure variety
    function testFuzz_property(address eoaCaller, uint256 /*unusedSalt*/ ) public {
        // keep eoaCaller non-zero and distinct from this test contract to be meaningful
        vm.assume(eoaCaller != address(0));
        vm.assume(eoaCaller != address(this));

        // Deploy a forwarding contract that will call c.owner() and return the value observed as its view
        CallerForward forward = new CallerForward();

        // make the EOA fund the forwarder so it can make calls (not strictly necessary for view but keeps scenario realistic)
        vm.deal(eoaCaller, 1 ether);

        // Have the EOA call the forwarder which in turn calls c.owner()
        vm.prank(eoaCaller);
        address observedFromForward = forward.readOwner(address(c));

        // Direct call by EOA to c.owner()
        vm.prank(eoaCaller);
        address observedDirect = c.owner();

        // The general rule: the true contract returns the stored deployer (which is address(this) from setUp())
        // when read directly or through a forwarder contract the reference implementation will still return the same stored owner
        // whereas the mutant returning tx.origin would return the EOA origin when called through the forwarder, causing a difference.
        // Assert the universal property: owner() observed via forwarder equals owner() observed directly (one assertion)
        assertTrue(observedFromForward == observedDirect);
    }
}

// Minimal helper: a contract that forwards a call to C.owner() and returns the result
contract CallerForward {
    function readOwner(address target) external returns (address) {
        // call the public owner() and return result
        return C(target).owner();
    }
}

