import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzzed parameter is the candidate newOwner address
    function testFuzz_property(address newOwner) public {
        // We only need to consider any address; keep domain wide.
        // The general rule: calling transferOwnership(address(0)) must revert on the reference implementation
        // so we check whether calling transferOwnership with the fuzzed address succeeds.

        bool ok;
        // onlyOwner modifier applies; we are the owner (deployer), so call directly
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: for all inputs, the reference implementation must make transferOwnership(address(0)) fail.
        // We express this by asserting that if newOwner == address(0) then the call did NOT succeed (ok == false).
        // This holds for the reference; the mutant removes the require and will make ok == true for newOwner == address(0),
        // thus the test will fail on the mutant for some input (newOwner == address(0)).
        assertTrue(!(newOwner == address(0) && ok));
    }
}

