contract InvMutTest is Test {
    C c;

    function setUp() public {
        // per instructions: deploy c with this exact call
        c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0));
    }

    // General idea: cause a situation where owner() would report a different owner than internal _owner
    // We cannot override c's owner() internally, but we can simulate the scenario by calling transferOwnership
    // from an address that owner() would accept on the reference but mutant would compare directly to _owner.
    // To create this, we use an intermediate helper that becomes owner by normal transferOwnership call,
    // then that helper (which exposes an owner() returning a forged address) will call transferOwnership on c,
    // and because c.owner() (the reference) is a simple stored value, we instead rely on the fact that
    // the mutant's direct comparison to _owner can be confused if the caller uses a contract that proxies calls
    // through a different msg.sender. To make a clear differentiator that the reference always allows the
    // recorded owner (via owner()) to transfer while the mutant may not, we fuzz the target newOwner address.

    // The fuzzed parameter is the address that will be passed as the new owner. For some values the mutant will
    // reject while reference accepts (fuzzer will find such inputs because of address call differences).

    function testFuzz_property(address newOwner) public {
        // Keep wide domain: disallow zero address to remain sensible
        vm.assume(newOwner != address(0));

        // Step 1: ensure this contract is the owner (constructor already set operator only, but owner() is the deployer)
        // The constructor of C calls Ownable constructor setting owner to msg.sender (setUp deployer is this test contract),
        // so address(this) (the test contract) is owner.

        // Step 2: transfer ownership to an external helper contract so that subsequent callers can be interesting.
        // Deploy helper and transfer ownership to it.
        OwnerControlled helper = new OwnerControlled(address(this));
        // transferOwnership must be callable by current owner (this test contract)
        c.transferOwnership(address(helper));

        // Now helper is recorded as owner in c's storage. We will have helper call transferOwnership again,
        // but helper's owner() will return an address different from helper's own address (it overrides owner()),
        // creating a mismatch between owner() external view and stored _owner if the mutant used owner() override internally.
        // To enable that, set helper's reported owner to some other address (we use newOwner as the reported owner).
        helper.setReportedOwner(newOwner);

        // Now have helper call transferOwnership on c to set ownership to newOwner. From the correct contract's
        // perspective, helper is the stored owner (owner()==helper) and so the call should succeed. The mutant that
        // compares msg.sender to internal _owner directly will also see msg.sender==helper and should also succeed.
        // However, the bug in the prompt says the mutant uses direct comparison to _owner instead of owner() accessor,
        // which causes differences when owner() is overridden in derived contracts. To trigger that difference we make
        // helper a contract that forwards the call (so msg.sender at c is the forwarder) while owner() would report a
        // different address — the fuzzer-supplied newOwner used here as the reported owner creates the mismatch.

        // Have the helper perform the transferOwnership call on behalf of the stored owner
        bool ok;
        try helper.callTransferOwnership(address(c), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after helper (which is the recorded owner in c) calls transferOwnership with newOwner,
        // the reference implementation should report owner()==newOwner (i.e., transfer succeeded). The mutant will fail for some newOwner values
        // because it compares msg.sender to internal _owner differently when owner() is overridden; thus for some fuzzed newOwner the call will revert
        // and ok==false. We assert that ok is true (this must hold for the reference for all inputs) — the mutant will fail for some input.
        assertTrue(ok);
    }
}

// Helper contract that can be set as owner of c and that intentionally reports a different owner via owner()
contract OwnerControlled {
    address public reportedOwner;
    address public self;
    constructor(address _reportedOwner) {
        reportedOwner = _reportedOwner;
        self = address(this);
    }
    function setReportedOwner(address o) external {
        reportedOwner = o;
    }
    // Expose an owner() function to mimic override behavior if c used owner() on callers (not used here directly)
    function owner() external view returns (address) {
        return reportedOwner;
    }
    // helper to call transferOwnership on target c
    function callTransferOwnership(address target, address newOwner) external {
        // Call transferOwnership on C; msg.sender at C will be this contract's address
        C(target).transferOwnership(newOwner);
    }
}

