// Helper that overrides owner() to return address(this) and forwards transferOwnership call to target C
contract OverridingOwner {
    C public target;
    constructor(address _target) {
        target = C(_target);
    }

    // override owner() accessibility to mimic Ownable override
    function owner() public view returns (address) {
        return address(this);
    }

    // helper to call transferOwnership on target
    function callTransferOwnership(address newOwner) external {
        // call as this contract
        target.transferOwnership(newOwner);
    }
}

